"""
    Helper function to generate a new column which will be used
    to label the choropleth maps. Function used to label missing data
    (otherwise they will show up on the map as "-1 SEK").

    Parameters
    ----------
    row :

    Returns
    -------
    str
        Column label to show when user hovers mouse over a choropleth map.
    """
def create_label_column(row: Any) -> str {
    if (row["Median Rent (SEK)"] > 0) {
        return ("Median Cost: " + str(int(row["Median Rent (SEK)"])) + " SEK");
    } else {
        return "Missing Data";
    }
}

"""Calculate accuracy for multiple choice tasks.

    Args:
        pred_dict: mapping subinstance ids to prediction, where subinstance id is like "0_0", which stands for the 0-th
            option for the 0-th instance
        labels_dict: mapping subinstance ids to labels
    Return:
        accuracy: measuring the percentage of correct predicted instances
    """
def calculate_multiple_choice_task_metrics(pred_dict: Any, labels_dict: Any) -> object {
    assert (len(pred_dict) == len(labels_dict));
    instance = `dict();
    for sub_id in pred_dict {
        (ins_id, choice_id) = sub_id.split("_");
        prob = pred_dict[sub_id];
        if not (ins_id in instance) {
            instance[ins_id] = (choice_id, prob);
        } elif (prob > instance[ins_id][1]) {
            instance[ins_id] = (choice_id, prob);
        }
    }
    correct_count = 0;
    for sub_id in labels_dict {
        (ins_id, choice_id) = sub_id.split("_");
        label = int(labels_dict[sub_id]);
        if ((label == 1) and (choice_id == instance[ins_id][0])) {
            correct_count += 1;
        }
    }
    return (correct_count / len(instance));
}

""" Convert x,y chromaticity coordinates to XYZ tristimulus values.
    """
def triwhite(x: Any, y: Any) -> object {
    X = x / y;
    Y = 1.0;
    Z = (1 - x - y) / y;
    return [X, Y, Z];
}

